import pandas as pd

jan_sales = pd.DataFrame({
    'product': ['Widget A', 'Widget B', 'Widget C'],
    'units_sold': [120, 85, 60],
    'revenue': [1200, 850, 600],
    'promo_code': ['JAN10', None, 'JAN10']
})

feb_sales = pd.DataFrame({
    'product': ['Widget A', 'Widget B', 'Widget C'],
    'units_sold': [140, 90, 75],
    'revenue': [1400, 900, 750]
})

mar_sales = pd.DataFrame({
    'product': ['Widget A', 'Widget B', 'Widget C'],
    'units_sold': [130, 95, 80],
    'revenue': [1300, 950, 800]
})

q1_sales = pd.concat([jan_sales, feb_sales, mar_sales], ignore_index=True)
print(q1_sales)
